import { forwardRef, type ReactNode } from "react";
import { cn } from "@/lib/cn";
import { Checkbox, type CheckboxProps } from "./checkbox.js";
import { IconChoiceMark } from "./icon-choice-mark.js";

/** Props accepted by IconCheckbox. The full label names the native input. */
export type IconCheckboxProps = {
  label: string;
  icon: ReactNode;
  /** A short visible legend; it does not replace the accessible label. */
  caption?: string;
  /** Compact instruments show the icon and caption without a tile or lamp. */
  appearance?: "default" | "compact";
} & Omit<CheckboxProps, "children" | "indicator">;

/** An independent icon choice composed from the native Caps Checkbox. */
export const IconCheckbox = forwardRef<HTMLInputElement, IconCheckboxProps>(
  function IconCheckbox(
    { label, icon, caption, appearance, className, ...props },
    ref,
  ) {
    return (
      <label
        className="caps-icon-choice"
        data-appearance={appearance === "compact" ? appearance : undefined}
      >
        <Checkbox
          {...props}
          appearance={appearance ?? "default"}
          aria-label={label}
          className={cn("caps-icon-choice-input", className)}
          indicator={<IconChoiceMark icon={icon} caption={caption} />}
          ref={ref}
        />
      </label>
    );
  },
);

import type { ReactNode } from "react";

/** The decorative face shared by icon choices; its native input names it. */
export function IconChoiceMark({
  icon,
  caption,
}: {
  icon: ReactNode;
  caption?: string | undefined;
}) {
  return (
    <span className="caps-icon-choice-mark" aria-hidden="true">
      <span className="caps-icon-choice-art">{icon}</span>
      {caption ? (
        <span className="caps-icon-choice-caption">{caption}</span>
      ) : null}
      <span className="caps-icon-choice-lamp" />
    </span>
  );
}

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}
